tool_input.command:
mkdir -p $TMPDIR/jtest && cat > $TMPDIR/jtest/T.java <<'EOF'
import java.text.MessageFormat;
public class T {
    public static void main(String[] a) throws Exception {
        try {
            MessageFormat mf = new MessageFormat("'{0}");
            System.out.println("no exception: pattern=[" + mf.toPattern() + "]");
            System.out.println("format: [" + mf.format(new Object[]{"X"}) + "]");
        } catch (Exception e) {
            System.out.println("threw: " + e);
        }
        try {
            MessageFormat mf2 = new MessageFormat("'{0} XX");
            System.out.println("no exception2: pattern=[" + mf2.toPattern() + "]");
        } catch (Exception e) {
            System.out.println("threw2: " + e);
        }
    }
}
EOF
cd $TMPDIR/jtest && javac T.java && java T
